488-0.00723743723790103i -0.0271981732486685+0.0622625840617741i 0.0763868134281137+0.0463123823769363i -0.0454657527569098+0.00835960211018294i -0.0775768614779203-0.0216454366128421i -0.00408801676288306+0.116777228956787i 0.0943759941811672+0.0720506500615684i 0.104968002470594+0.00147894784371714i 0.0852924303568157-0.0502874587623375i -0.0168170060195467-0.081102505193724i 0.0781879404485611+0.0314691990558253i -0.0944481700948903+0.034681820798881i -0.139745763757582+0.0765485959924427i -0.0657530030577363-0.00579221355004928i 0.0488191185642004+0.0600737253506407i -0.00732479670985871+0.0272673076900136i -0.0554637031891375-0.0488367879056767i -0.0704436285081668-0.0858794303668759i 0.0339020233861118-0.0987355704339731i -0.0836215656422093-0.0103801723131123i 0.0247559094878967-0.0530146121996761i -0.0739635833873378-0.170963499986694i];
    R_m = (W_m*(y_v+N_m)*sqrt(consEnergy)+(1+1j))/2;
    R_m_real = max(-M/2+1, min(round(real(R_m)), M/2));
    R_m_imag = max(-M/2+1, min(round(imag(R_m)), M/2));
    R_m = R_m_real+1j*R_m_imag;
    R_m = (2*round(R_m)-(1+1j))/sqrt(consEnergy);
    
%     for i=1:samples
%         n_v = (randn(Nr, 1) + 1j*randn(Nr, 1)) * sqrt(N0);
%         R_m(:, i) = W_m*(y_v+N_m(:, i));
%         [~, R_m(:, i)] = min((R_m(:, i)-cons).^2, [], 2);
%         R_m(:, i) = cons(R_m(:, i)).';
%     end

    [uniqueVecs, ~, idx] = unique(R_m.', 'rows');
    counts = histcounts(idx, 1:max(idx)+1);
    frequentIdx = counts > floor(samples*2e-3);

    F_m = uniqueVecs(frequentIdx, :).';

    if ~ismember(r_v.', F_m.', 'rows')
        F_m = [F_m r_v]; % Append r_v as a new column
    end

    [~, idx] = min(vecnorm(y_v-H_m*F_m));

    r_v = F_m(:, idx);
    [~, r_v] = min((r_v-cons).^2, [], 2);
    simTime = toc;
end